/// </summary>
public record ProviderCapabilities (
    bool @supportsClientCapabilitiesRegistration, 
    bool @supportsPlaybackProgressReporting, 
    bool @supportsSidecarLyricsLookup, 
    bool @supportsServerLyrics, 
    bool @supportsInstantMix
) {
}

class FfiConverterTypeProviderCapabilities: FfiConverterRustBuffer<ProviderCapabilities> {
    public static FfiConverterTypeProviderCapabilities INSTANCE = new FfiConverterTypeProviderCapabilities();

    public override ProviderCapabilities Read(BigEndianStream stream) {
        return new ProviderCapabilities(
            @supportsClientCapabilitiesRegistration: FfiConverterBoolean.INSTANCE.Read(stream),
            @supportsPlaybackProgressReporting: FfiConverterBoolean.INSTANCE.Read(stream),
            @supportsSidecarLyricsLookup: FfiConverterBoolean.INSTANCE.Read(stream),
            @supportsServerLyrics: FfiConverterBoolean.INSTANCE.Read(stream),
            @supportsInstantMix: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(ProviderCapabilities value) {
        return 0
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@supportsClientCapabilitiesRegistration)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@supportsPlaybackProgressReporting)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@supportsSidecarLyricsLookup)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@supportsServerLyrics)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@supportsInstantMix);
    }

    public override void Write(ProviderCapabilities value, BigEndianStream stream) {
            FfiConverterBoolean.INSTANCE.Write(value.@supportsClientCapabilitiesRegistration, stream);
            FfiConverterBoolean.INSTANCE.Write(value.@supportsPlaybackProgressReporting, stream);
            FfiConverterBoolean.INSTANCE.Write(value.@supportsSidecarLyricsLookup, stream);
            FfiConverterBoolean.INSTANCE.Write(value.@supportsServerLyrics, stream);
            FfiConverterBoolean.INSTANCE.Write(value.@supportsInstantMix, stream);
    }
}



/// <summary>
/// Song representing a music track or audio file
/// </summary>
/// <param name="id">
/// Unique identifier
/// </param>
/// <param name="name">
/// Song title
/// </param>
/// <param name="item_type">
/// Type of item (usually "Audio")
/// </param>
/// <param name="album">
/// Album name
/// </param>
/// <param name="album_id">
/// Album ID
/// </param>
/// <param name="artists">
/// List of artist names
/// </param>
/// <param name="artist_ids">
/// List of artist IDs corresponding to artists
/// </param>
/// <param name="path">
/// File path
/// </param>
/// <param name="duration">
/// Duration in seconds
/// </param>
/// <param name="album_art_url">
/// URL to album artwork
/// </param>
/// <param name="year">
/// Release year
/// </param>
/// <param name="play_count">
/// Number of times played
/// </param>
/// <param name="is_favorite">
/// Whether this item is marked as favorite
/// </param>
/// <param name="disc_number">
/// Disc number in album
/// </param>
/// <param name="track_number">
/// Track number in album
/// </param>
/// <param name="container">
/// Audio container/format
/// </param>
/// <param name="bit_rate">
/// Audio bitrate
/// </param>
/// <param name="sample_rate">
/// Audio sample rate
/// </param>
/// <param name="codec">
/// Audio codec
/// </param>
/// <param name="genres">
/// Music genres
/// </param>
/// <param name="premiere_date">
/// Premiere/release date
/// </param>
/// <param name="date_played">
/// Last played date
/// </param>
/// <param name="date_created">
/// Date created (when added to server)
/// </param>
/// <param name="date_modified">
/// Date last modified on server
/// </param>
/// <param name="album_artists">
/// Album artists (different from track artists)
/// </param>
/// <param name="lyrics">
/// Song lyrics
/// </param>
/// <param name="image_tags">
/// Image tags
/// </param>
public record Song (
    /// <summary>
    /// Unique identifier
    /// </summary>
    string @id, 
    /// <summary>
    /// Song title
    /// </summary>
    string @name, 
    /// <summary>
    /// Type of item (usually "Audio")
    /// </summary>
    string @itemType, 
    /// <summary>
    /// Album name
    /// </summary>
    string? @album, 
    /// <summary>
    /// Album ID
    /// </summary>
    string? @albumId, 
    /// <summary>
    /// List of artist names
    /// </summary>
    string[]? @artists, 
    /// <summary>
    /// List of artist IDs corresponding to artists
    /// </summary>
    string[]? @artistIds, 
    /// <summary>
    /// File path
    /// </summary>
    string? @path, 
    /// <summary>
    /// Duration in seconds
    /// </summary>
    double? @duration, 
    /// <summary>
    /// URL to album artwork
    /// </summary>
    string? @albumArtUrl, 
    /// <summary>
    /// Release year
    /// </summary>
    int? @year, 
    /// <summary>
    /// Number of times played
    /// </summary>
    int? @playCount, 
    /// <summary>
    /// Whether this item is marked as favorite
    /// </summary>
    bool? @isFavorite, 
    /// <summary>
    /// Disc number in album
    /// </summary>
    int? @discNumber, 
    /// <summary>
    /// Track number in album
    /// </summary>
    int? @trackNumber, 
    /// <summary>
    /// Audio container/format
    /// </summary>
    string? @container, 
    /// <summary>
    /// Audio bitrate
    /// </summary>
    int? @bitRate, 
    /// <summary>
    /// Audio sample rate
    /// </summary>
    int? @sampleRate, 
    /// <summary>
    /// Audio codec
    /// </summary>
    string? @codec, 
    /// <summary>
    /// Music genres
    /// </summary>
    string[]? @genres, 
    /// <summary>
    /// Premiere/release date
    /// </summary>
    string? @premiereDate, 
    /// <summary>
    /// Last played date
    /// </summary>
    string? @datePlayed, 
    /// <summary>
    /// Date created (when added to server)
    /// </summary>
    string? @dateCreated, 
    /// <summary>
    /// Date last modified on server
    /// </summary>
    string? @dateModified, 
    /// <summary>
    /// Album artists (different from track artists)
    /// </summary>
    NameIdPair[]? @albumArtists, 
    /// <summary>
    /// Song lyrics
    /// </summary>
    string? @lyrics, 
    /// <summary>
    /// Image tags
    /// </summary>
    Dictionary<string, string>? @imageTags
) {
}

