/// <summary>
/// Progress update during sync (for UI feedback)
/// </summary>
/// <param name="stage">
/// Current stage of sync (e.g., "Fetching songs", "Saving to database")
/// </param>
/// <param name="current">
/// Current item being processed
/// </param>
/// <param name="total">
/// Total items to process
/// </param>
/// <param name="is_complete">
/// Whether sync is complete
/// </param>
public record SyncProgress (
    /// <summary>
    /// Current stage of sync (e.g., "Fetching songs", "Saving to database")
    /// </summary>
    string @stage, 
    /// <summary>
    /// Current item being processed
    /// </summary>
    uint @current, 
    /// <summary>
    /// Total items to process
    /// </summary>
    uint @total, 
    /// <summary>
    /// Whether sync is complete
    /// </summary>
    bool @isComplete
) {
}

class FfiConverterTypeSyncProgress: FfiConverterRustBuffer<SyncProgress> {
    public static FfiConverterTypeSyncProgress INSTANCE = new FfiConverterTypeSyncProgress();

    public override SyncProgress Read(BigEndianStream stream) {
        return new SyncProgress(
            @stage: FfiConverterString.INSTANCE.Read(stream),
            @current: FfiConverterUInt32.INSTANCE.Read(stream),
            @total: FfiConverterUInt32.INSTANCE.Read(stream),
            @isComplete: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(SyncProgress value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.@stage)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@current)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@total)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@isComplete);
    }

    public override void Write(SyncProgress value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.@stage, stream);
            FfiConverterUInt32.INSTANCE.Write(value.@current, stream);
            FfiConverterUInt32.INSTANCE.Write(value.@total, stream);
            FfiConverterBoolean.INSTANCE.Write(value.@isComplete, stream);
    }
}



