/// <summary>
/// Sync state persisted to track library sync history
/// </summary>
/// <param name="full_sync_in_progress">
/// Whether a full sync is currently in progress (for resumability)
/// </param>
/// <param name="full_sync_last_page_index">
/// The last page index that was successfully committed during a full sync
/// </param>
/// <param name="full_sync_entity_type">
/// Which entity type the in-progress full sync is on: "songs", "albums", "artists", or "done"
/// </param>
public record SyncState (
    string @lastSyncTime, 
    string? @lastFullSyncTime, 
    string? @lastSyncVersion, 
    uint @songCount, 
    uint @artistCount, 
    uint @albumCount, 
    /// <summary>
    /// Whether a full sync is currently in progress (for resumability)
    /// </summary>
    bool @fullSyncInProgress, 
    /// <summary>
    /// The last page index that was successfully committed during a full sync
    /// </summary>
    uint @fullSyncLastPageIndex, 
    /// <summary>
    /// Which entity type the in-progress full sync is on: "songs", "albums", "artists", or "done"
    /// </summary>
    string? @fullSyncEntityType
) {
}

class FfiConverterTypeSyncState: FfiConverterRustBuffer<SyncState> {
    public static FfiConverterTypeSyncState INSTANCE = new FfiConverterTypeSyncState();

    public override SyncState Read(BigEndianStream stream) {
        return new SyncState(
            @lastSyncTime: FfiConverterString.INSTANCE.Read(stream),
            @lastFullSyncTime: FfiConverterOptionalString.INSTANCE.Read(stream),
            @lastSyncVersion: FfiConverterOptionalString.INSTANCE.Read(stream),
            @songCount: FfiConverterUInt32.INSTANCE.Read(stream),
            @artistCount: FfiConverterUInt32.INSTANCE.Read(stream),
            @albumCount: FfiConverterUInt32.INSTANCE.Read(stream),
            @fullSyncInProgress: FfiConverterBoolean.INSTANCE.Read(stream),
            @fullSyncLastPageIndex: FfiConverterUInt32.INSTANCE.Read(stream),
            @fullSyncEntityType: FfiConverterOptionalString.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(SyncState value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.@lastSyncTime)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.@lastFullSyncTime)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.@lastSyncVersion)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@songCount)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@artistCount)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@albumCount)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.@fullSyncInProgress)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@fullSyncLastPageIndex)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.@fullSyncEntityType);
    }

    public override void Write(SyncState value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.@lastSyncTime, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.@lastFullSyncTime, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.@lastSyncVersion, stream);
            FfiConverterUInt32.INSTANCE.Write(value.@songCount, stream);
            FfiConverterUInt32.INSTANCE.Write(value.@artistCount, stream);
            FfiConverterUInt32.INSTANCE.Write(value.@albumCount, stream);
            FfiConverterBoolean.INSTANCE.Write(value.@fullSyncInProgress, stream);
            FfiConverterUInt32.INSTANCE.Write(value.@fullSyncLastPageIndex, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.@fullSyncEntityType, stream);
    }
}



