/// <summary>
/// Application-specific error type using thiserror
/// </summary>
public class AppException: UniffiException {
    AppException() : base() {}
    AppException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class Network : AppException {
        // Members
        public string @v1;

        // Constructor
        public Network(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Auth : AppException {
        // Members
        public string @v1;

        // Constructor
        public Auth(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Database : AppException {
        // Members
        public string @v1;

        // Constructor
        public Database(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Serialization : AppException {
        // Members
        public string @v1;

        // Constructor
        public Serialization(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class FileSystem : AppException {
        // Members
        public string @v1;

        // Constructor
        public FileSystem(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class ApiParse : AppException {
        // Members
        public string @v1;

        // Constructor
        public ApiParse(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Config : AppException {
        // Members
        public string @v1;

        // Constructor
        public Config(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class Http : AppException {
        // Members
        public ushort @status;
        public string @detail;

        // Constructor
        public Http(
                ushort @status, 
                string @detail) : base(
                "@status" + "=" + @status+ ", " +
                "@detail" + "=" + @detail) {

            this.@status = @status;

            this.@detail = @detail;
        }
    }
    
    
    public class General : AppException {
        // Members
        public string @v1;

        // Constructor
        public General(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    
    
    public class UniFfi : AppException {
        // Members
        public string @v1;

        // Constructor
        public UniFfi(
                string @v1) : base(
                "@v1" + "=" + @v1) {

            this.@v1 = @v1;
        }
    }
    

    
}

class FfiConverterTypeAppError : FfiConverterRustBuffer<AppException>, CallStatusErrorHandler<AppException> {
    public static FfiConverterTypeAppError INSTANCE = new FfiConverterTypeAppError();

    public override AppException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new AppException.Network(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new AppException.Auth(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new AppException.Database(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new AppException.Serialization(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new AppException.FileSystem(
                    FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new AppException.ApiParse(
                    FfiConverterString.INSTANCE.Read(stream));
            case 7:
                return new AppException.Config(
                    FfiConverterString.INSTANCE.Read(stream));
            case 8:
                return new AppException.Http(
                    FfiConverterUInt16.INSTANCE.Read(stream),
